insert into kafaa_smr_deltas (id, role_id, tech_id, rank, path_only, dims, changes_en, changes_ar, stays_en, stays_ar, skills, training, concept_role_ids, sources, benchmark_ids, status, listed, version, as_of, sort, updated_by, updated_at) values
('smrd:chemistry-technician:tech-fast', 'chemistry-technician', 'tech-fast', 2, false, '[{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation designed for liquid-metal coolant and a fast neutron spectrum. Online chemistry monitoring and trending tools.","text_ar":"أجهزة مصممة لمبرد معدني سائل وطيف نيوتروني سريع. أدوات مراقبة الكيمياء وتحليل الاتجاهات عبر الإنترنت."},{"dim":"maintenance","change":"new","text_en":"Liquid-metal coolant changes how components are inspected, drained and handled. New sampling points, analytical methods and laboratory QA.","text_ar":"يغيّر المبرد المعدني السائل طريقة فحص المكونات وتصريفها ومناولتها. نقاط أخذ عينات وطرق تحليل وضمان جودة مختبري جديدة."},{"dim":"systems","change":"new","text_en":"Liquid-metal coolant handling and chemistry, and fast-spectrum reactor physics. Coolant chemistry changes completely, from water chemistry to the chemistry of the new coolant.","text_ar":"مناولة المبرد المعدني السائل وكيمياؤه، وفيزياء المفاعلات ذات الطيف السريع. تتغير كيمياء المبرد كلياً، من كيمياء الماء إلى كيمياء المبرد الجديد."}]'::jsonb, 'Fast reactors with liquid-metal coolant: the biggest shifts for this role are the maintenance regime and plant systems, coolant and fuel; digital I&C adapts. Planning assumption; no deployment decision implied.', 'المفاعلات السريعة المبرّدة بالمعادن السائلة: أكبر التحولات لهذا الدور في نظام الصيانة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من الأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Sampling discipline, laboratory QA and effluent monitoring principles stay the same.', 'يبقى انضباط أخذ العينات وضمان جودة المختبر ومبادئ مراقبة الانبعاثات كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-ch-01-advchem","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 44, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:chemistry-technician:tech-bwr', 'chemistry-technician', 'tech-bwr', 3, false, '[{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. Online chemistry monitoring and trending tools.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. أدوات مراقبة الكيمياء وتحليل الاتجاهات عبر الإنترنت."},{"dim":"maintenance","change":"adapts","text_en":"Maintenance windows and refuelling follow a different design basis and outage rhythm. New sampling points, analytical methods and laboratory QA.","text_ar":"تتبع نوافذ الصيانة والتزويد بالوقود أساس تصميم وإيقاع إيقاف مختلفين. نقاط أخذ عينات وطرق تحليل وضمان جودة مختبري جديدة."},{"dim":"systems","change":"new","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. Coolant chemistry changes completely, from water chemistry to the chemistry of the new coolant.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. تتغير كيمياء المبرد كلياً، من كيمياء الماء إلى كيمياء المبرد الجديد."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are plant systems, coolant and fuel; digital I&C and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في أنظمة المحطة والمبرد والوقود، بينما يتكيف كل من الأجهزة والتحكم الرقمية، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Sampling discipline, laboratory QA and effluent monitoring principles stay the same.', 'يبقى انضباط أخذ العينات وضمان جودة المختبر ومبادئ مراقبة الانبعاثات كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 45, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:environmental-monitoring-specialist:tech-bwr', 'environmental-monitoring-specialist', 'tech-bwr', 1, false, '[{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. Remote environmental sensors and data platforms.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. مستشعرات بيئية عن بعد ومنصات بيانات."},{"dim":"systems","change":"new","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. Different effluents and environmental pathways to model and monitor.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. انبعاثات ومسارات بيئية مختلفة للنمذجة والمراقبة."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are plant systems, coolant and fuel; digital I&C adapts. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في أنظمة المحطة والمبرد والوقود، بينما يتكيف كل من الأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Radiological environmental monitoring principles and public reporting stay the same.', 'تبقى مبادئ الرصد الإشعاعي البيئي والإبلاغ العام كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 46, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:environmental-monitoring-specialist:tech-htgr', 'environmental-monitoring-specialist', 'tech-htgr', 2, false, '[{"dim":"digital_ic","change":"adapts","text_en":"New digital instrumentation for gas coolant and high-temperature systems. Remote environmental sensors and data platforms.","text_ar":"أجهزة رقمية جديدة لأنظمة التبريد بالغاز والأنظمة عالية الحرارة. مستشعرات بيئية عن بعد ومنصات بيانات."},{"dim":"systems","change":"new","text_en":"Gas coolant, a different fuel form and high-temperature heat that can also serve industrial processes. Different effluents and environmental pathways to model and monitor.","text_ar":"تبريد بالغاز وشكل وقود مختلف وحرارة عالية يمكن أن تخدم العمليات الصناعية أيضاً. انبعاثات ومسارات بيئية مختلفة للنمذجة والمراقبة."}]'::jsonb, 'High-temperature gas-cooled: the biggest shifts for this role are plant systems, coolant and fuel; digital I&C adapts. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: أكبر التحولات لهذا الدور في أنظمة المحطة والمبرد والوقود، بينما يتكيف كل من الأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Radiological environmental monitoring principles and public reporting stay the same.', 'تبقى مبادئ الرصد الإشعاعي البيئي والإبلاغ العام كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"lane","ref":"lane-hydrogen"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 47, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:environmental-monitoring-specialist:tech-msr', 'environmental-monitoring-specialist', 'tech-msr', 3, false, '[{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation and sampling designed for hot salt systems. Remote environmental sensors and data platforms.","text_ar":"أجهزة وأخذ عينات مصممة لأنظمة الأملاح الساخنة. مستشعرات بيئية عن بعد ومنصات بيانات."},{"dim":"systems","change":"new","text_en":"Salt chemistry and materials replace water chemistry. Different effluents and environmental pathways to model and monitor.","text_ar":"تحل كيمياء الأملاح وموادها محل كيمياء الماء. انبعاثات ومسارات بيئية مختلفة للنمذجة والمراقبة."}]'::jsonb, 'Molten salt: the biggest shifts for this role are plant systems, coolant and fuel; digital I&C adapts. Planning assumption; no deployment decision implied.', 'مفاعلات الأملاح المنصهرة: أكبر التحولات لهذا الدور في أنظمة المحطة والمبرد والوقود، بينما يتكيف كل من الأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Radiological environmental monitoring principles and public reporting stay the same.', 'تبقى مبادئ الرصد الإشعاعي البيئي والإبلاغ العام كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 48, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:quality-assurance-qc:tech-bwr', 'quality-assurance-qc', 'tech-bwr', 1, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. Identical modules make sampling plans and trend analysis across units possible.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. تتيح الوحدات المتطابقة خطط أخذ عينات وتحليل اتجاهات عبر الوحدات."},{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. Digital records and software quality join hardware quality.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. تنضم السجلات الرقمية وجودة البرمجيات إلى جودة المعدات."},{"dim":"factory_fab","change":"adapts","text_en":"More of the plant arrives as factory-built modules, so quality evidence moves upstream to the factory. Quality oversight moves into the factory: source inspection, factory acceptance tests and supplier audits.","text_ar":"يصل جزء أكبر من المحطة على شكل وحدات مصنّعة في المصنع، فتنتقل أدلة الجودة إلى المصنع. تنتقل رقابة الجودة إلى المصنع: فحص المصدر واختبارات القبول في المصنع وتدقيق الموردين."},{"dim":"systems","change":"adapts","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. New materials and coolants bring new inspection techniques.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. تجلب المواد والمبردات الجديدة تقنيات فحص جديدة."}]'::jsonb, 'Small boiling water reactor: for this role multi-module operation, digital I&C, factory fabrication and plant systems, coolant and fuel adapt; the rest stays close to today. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: في هذا الدور يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، وأنظمة المحطة والمبرد والوقود، ويبقى الباقي قريباً مما هو عليه اليوم. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'NQA-1 discipline, independence and reliance on objective evidence stay the same.', 'يبقى انضباط NQA-1 والاستقلالية والاعتماد على الأدلة الموضوعية كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 49, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:quality-assurance-qc:tech-htgr', 'quality-assurance-qc', 'tech-htgr', 2, false, '[{"dim":"multi_module","change":"new","text_en":"Several smaller reactor modules may share one plant and one control room. Identical modules make sampling plans and trend analysis across units possible.","text_ar":"قد تتشارك عدة وحدات مفاعل أصغر محطة واحدة وغرفة تحكم واحدة. تتيح الوحدات المتطابقة خطط أخذ عينات وتحليل اتجاهات عبر الوحدات."},{"dim":"digital_ic","change":"adapts","text_en":"New digital instrumentation for gas coolant and high-temperature systems. Digital records and software quality join hardware quality.","text_ar":"أجهزة رقمية جديدة لأنظمة التبريد بالغاز والأنظمة عالية الحرارة. تنضم السجلات الرقمية وجودة البرمجيات إلى جودة المعدات."},{"dim":"factory_fab","change":"new","text_en":"Reactor modules and major components are planned to be factory-built. Quality oversight moves into the factory: source inspection, factory acceptance tests and supplier audits.","text_ar":"يُخطَّط لتصنيع وحدات المفاعل والمكونات الرئيسية في المصنع. تنتقل رقابة الجودة إلى المصنع: فحص المصدر واختبارات القبول في المصنع وتدقيق الموردين."},{"dim":"systems","change":"adapts","text_en":"Gas coolant, a different fuel form and high-temperature heat that can also serve industrial processes. New materials and coolants bring new inspection techniques.","text_ar":"تبريد بالغاز وشكل وقود مختلف وحرارة عالية يمكن أن تخدم العمليات الصناعية أيضاً. تجلب المواد والمبردات الجديدة تقنيات فحص جديدة."}]'::jsonb, 'High-temperature gas-cooled: the biggest shifts for this role are multi-module operation and factory fabrication; digital I&C and plant systems, coolant and fuel adapt. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: أكبر التحولات لهذا الدور في التشغيل متعدد الوحدات، والتصنيع في المصنع، بينما يتكيف كل من الأجهزة والتحكم الرقمية، وأنظمة المحطة والمبرد والوقود. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'NQA-1 discipline, independence and reliance on objective evidence stay the same.', 'يبقى انضباط NQA-1 والاستقلالية والاعتماد على الأدلة الموضوعية كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-hydrogen"}]'::jsonb, array['fr-ht-materials']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"osu-e2-center","label":"Oregon State University · NuScale Energy Exploration (E2) Center","url":"https://engineering.oregonstate.edu/facilities/energy-exploration-e2-center","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 50, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:quality-assurance-qc:tech-micro', 'quality-assurance-qc', 'tech-micro', 3, false, '[{"dim":"multi_module","change":"new","text_en":"Many small transportable units rather than one plant. Identical modules make sampling plans and trend analysis across units possible.","text_ar":"وحدات صغيرة كثيرة قابلة للنقل بدلاً من محطة واحدة. تتيح الوحدات المتطابقة خطط أخذ عينات وتحليل اتجاهات عبر الوحدات."},{"dim":"digital_ic","change":"adapts","text_en":"Remote and autonomous operation concepts: monitoring from a distance rather than from a local control room. Digital records and software quality join hardware quality.","text_ar":"مفاهيم التشغيل عن بعد والتشغيل الذاتي: المراقبة من بعيد بدلاً من غرفة تحكم محلية. تنضم السجلات الرقمية وجودة البرمجيات إلى جودة المعدات."},{"dim":"factory_fab","change":"new","text_en":"Units are built in a factory and transported as complete units. Quality oversight moves into the factory: source inspection, factory acceptance tests and supplier audits.","text_ar":"تُبنى الوحدات في المصنع وتُنقل وحدات كاملة. تنتقل رقابة الجودة إلى المصنع: فحص المصدر واختبارات القبول في المصنع وتدقيق الموردين."},{"dim":"systems","change":"adapts","text_en":"Compact designs with their own coolant and fuel choices. New materials and coolants bring new inspection techniques.","text_ar":"تصاميم مدمجة لها خياراتها الخاصة من المبرد والوقود. تجلب المواد والمبردات الجديدة تقنيات فحص جديدة."}]'::jsonb, 'Microreactors: the biggest shifts for this role are multi-module operation and factory fabrication; digital I&C and plant systems, coolant and fuel adapt. Planning assumption; no deployment decision implied.', 'المفاعلات المتناهية الصغر: أكبر التحولات لهذا الدور في التشغيل متعدد الوحدات، والتصنيع في المصنع، بينما يتكيف كل من الأجهزة والتحكم الرقمية، وأنظمة المحطة والمبرد والوقود. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'NQA-1 discipline, independence and reliance on objective evidence stay the same.', 'يبقى انضباط NQA-1 والاستقلالية والاعتماد على الأدلة الموضوعية كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":2},{"skill_id":"sk-fs-adv-micro","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-adv-micro-l1"},{"kind":"course","ref":"c-fs-remote"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"osu-e2-center","label":"Oregon State University · NuScale Energy Exploration (E2) Center","url":"https://engineering.oregonstate.edu/facilities/energy-exploration-e2-center","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 51, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:nuclear-oversight-npi:tech-bwr', 'nuclear-oversight-npi', 'tech-bwr', 1, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. Performance trends and lessons learned compare several units.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. تقارن اتجاهات الأداء والدروس المستفادة بين عدة وحدات."},{"dim":"passive_safety","change":"new","text_en":"Small reactor designs put more weight on passive cooling that works for a period without AC power or operator action. Human performance shifts from manual action to monitoring passive systems and avoiding complacency.","text_ar":"تعطي تصاميم المفاعلات الصغيرة وزناً أكبر للتبريد الخامل الذي يعمل لفترة دون كهرباء متناوبة أو تدخل من المشغلين. ينتقل الأداء البشري من الإجراء اليدوي إلى مراقبة الأنظمة الخاملة وتجنب التراخي."},{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. Human-system interface reviews of new screens and alarms.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. مراجعات واجهة الإنسان والنظام للشاشات والإنذارات الجديدة."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are passive safety; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في السلامة الخاملة، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Safety culture traits, independent oversight and the corrective action programme stay the same.', 'تبقى سمات ثقافة السلامة والرقابة المستقلة وبرنامج الإجراءات التصحيحية كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-regulation","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 52, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:nuclear-oversight-npi:tech-micro', 'nuclear-oversight-npi', 'tech-micro', 2, false, '[{"dim":"multi_module","change":"adapts","text_en":"Many small transportable units rather than one plant. Performance trends and lessons learned compare several units.","text_ar":"وحدات صغيرة كثيرة قابلة للنقل بدلاً من محطة واحدة. تقارن اتجاهات الأداء والدروس المستفادة بين عدة وحدات."},{"dim":"passive_safety","change":"new","text_en":"Microreactor concepts are designed to cool themselves passively for long periods. Human performance shifts from manual action to monitoring passive systems and avoiding complacency.","text_ar":"صُممت مفاهيم المفاعلات المتناهية الصغر لتبريد نفسها بطريقة خاملة لفترات طويلة. ينتقل الأداء البشري من الإجراء اليدوي إلى مراقبة الأنظمة الخاملة وتجنب التراخي."},{"dim":"digital_ic","change":"adapts","text_en":"Remote and autonomous operation concepts: monitoring from a distance rather than from a local control room. Human-system interface reviews of new screens and alarms.","text_ar":"مفاهيم التشغيل عن بعد والتشغيل الذاتي: المراقبة من بعيد بدلاً من غرفة تحكم محلية. مراجعات واجهة الإنسان والنظام للشاشات والإنذارات الجديدة."}]'::jsonb, 'Microreactors: the biggest shifts for this role are passive safety; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'المفاعلات المتناهية الصغر: أكبر التحولات لهذا الدور في السلامة الخاملة، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Safety culture traits, independent oversight and the corrective action programme stay the same.', 'تبقى سمات ثقافة السلامة والرقابة المستقلة وبرنامج الإجراءات التصحيحية كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-regulation","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-adv-micro-l1"},{"kind":"course","ref":"c-fs-remote"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 53, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:nuclear-oversight-npi:tech-intl', 'nuclear-oversight-npi', 'tech-intl', 3, false, '[{"dim":"digital_ic","change":"adapts","text_en":"Different digital platforms and engineering tools from each partner. Human-system interface reviews of new screens and alarms.","text_ar":"منصات رقمية وأدوات هندسية مختلفة لدى كل شريك. مراجعات واجهة الإنسان والنظام للشاشات والإنذارات الجديدة."},{"dim":"delivery","change":"new","text_en":"Project delivery abroad, investment and owner''s-engineer work for partners. Independent oversight of work delivered with partners abroad.","text_ar":"تنفيذ المشاريع في الخارج والاستثمار وأعمال مهندس المالك للشركاء. رقابة مستقلة على الأعمال المنجزة مع الشركاء في الخارج."}]'::jsonb, 'International projects: the biggest shifts for this role are project delivery; digital I&C adapts. Planning assumption; no deployment decision implied.', 'المشاريع الدولية: أكبر التحولات لهذا الدور في تنفيذ المشاريع، بينما يتكيف كل من الأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Safety culture traits, independent oversight and the corrective action programme stay the same.', 'تبقى سمات ثقافة السلامة والرقابة المستقلة وبرنامج الإجراءات التصحيحية كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-en-01-project","level":1},{"skill_id":"sk-fs-adv-regulation","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"nucleareurope-match","label":"nucleareurope · MATCH programme: a tool for nuclear capacity building in France","url":"https://www.nucleareurope.eu/blog/highlight-of-the-month/match-program-a-tool-for-nuclear-capacity-building-in-france/","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 54, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:regulatory-affairs-licensing-engineer:tech-bwr', 'regulatory-affairs-licensing-engineer', 'tech-bwr', 1, false, '[{"dim":"passive_safety","change":"new","text_en":"Small reactor designs put more weight on passive cooling that works for a period without AC power or operator action. Safety cases built on passive features and longer coping times.","text_ar":"تعطي تصاميم المفاعلات الصغيرة وزناً أكبر للتبريد الخامل الذي يعمل لفترة دون كهرباء متناوبة أو تدخل من المشغلين. حالات سلامة مبنية على الخصائص الخاملة وفترات تحمّل أطول."},{"dim":"factory_fab","change":"adapts","text_en":"More of the plant arrives as factory-built modules, so quality evidence moves upstream to the factory. Licensing questions about factory quality and module transport.","text_ar":"يصل جزء أكبر من المحطة على شكل وحدات مصنّعة في المصنع، فتنتقل أدلة الجودة إلى المصنع. أسئلة ترخيص حول جودة المصنع ونقل الوحدات."},{"dim":"systems","change":"new","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. A new licensing basis: a different design, a different safety case and different regulatory questions.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. أساس ترخيص جديد: تصميم مختلف وحالة سلامة مختلفة وأسئلة تنظيمية مختلفة."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; factory fabrication adapts. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التصنيع في المصنع. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Tracking regulatory commitments and keeping a precise, honest licensing basis stay the same.', 'تبقى متابعة الالتزامات التنظيمية ودقة أساس الترخيص ونزاهته كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-fs-adv-regulation","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, array['fr-adv-licensing']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 55, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:regulatory-affairs-licensing-engineer:tech-htgr', 'regulatory-affairs-licensing-engineer', 'tech-htgr', 2, false, '[{"dim":"passive_safety","change":"new","text_en":"Gas-cooled designs aim to remove decay heat passively, relying on fuel and materials that tolerate high temperatures. Safety cases built on passive features and longer coping times.","text_ar":"تسعى التصاميم المبرّدة بالغاز إلى إزالة حرارة الاضمحلال بطريقة خاملة، معتمدة على وقود ومواد تتحمل درجات حرارة عالية. حالات سلامة مبنية على الخصائص الخاملة وفترات تحمّل أطول."},{"dim":"factory_fab","change":"adapts","text_en":"Reactor modules and major components are planned to be factory-built. Licensing questions about factory quality and module transport.","text_ar":"يُخطَّط لتصنيع وحدات المفاعل والمكونات الرئيسية في المصنع. أسئلة ترخيص حول جودة المصنع ونقل الوحدات."},{"dim":"systems","change":"new","text_en":"Gas coolant, a different fuel form and high-temperature heat that can also serve industrial processes. A new licensing basis: a different design, a different safety case and different regulatory questions.","text_ar":"تبريد بالغاز وشكل وقود مختلف وحرارة عالية يمكن أن تخدم العمليات الصناعية أيضاً. أساس ترخيص جديد: تصميم مختلف وحالة سلامة مختلفة وأسئلة تنظيمية مختلفة."}]'::jsonb, 'High-temperature gas-cooled: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; factory fabrication adapts. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التصنيع في المصنع. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Tracking regulatory commitments and keeping a precise, honest licensing basis stay the same.', 'تبقى متابعة الالتزامات التنظيمية ودقة أساس الترخيص ونزاهته كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-fs-adv-fuelcycle","level":2},{"skill_id":"sk-fs-adv-regulation","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"lane","ref":"lane-hydrogen"}]'::jsonb, array['fr-adv-licensing']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 56, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:regulatory-affairs-licensing-engineer:tech-fast', 'regulatory-affairs-licensing-engineer', 'tech-fast', 3, false, '[{"dim":"passive_safety","change":"new","text_en":"Fast-reactor concepts rely on passive heat removal through the coolant''s natural circulation. Safety cases built on passive features and longer coping times.","text_ar":"تعتمد مفاهيم المفاعلات السريعة على إزالة الحرارة بطريقة خاملة عبر الدوران الطبيعي للمبرد. حالات سلامة مبنية على الخصائص الخاملة وفترات تحمّل أطول."},{"dim":"factory_fab","change":"adapts","text_en":"More factory-built components and modular construction. Licensing questions about factory quality and module transport.","text_ar":"مكونات مصنّعة في المصنع وإنشاء معياري أكثر. أسئلة ترخيص حول جودة المصنع ونقل الوحدات."},{"dim":"systems","change":"new","text_en":"Liquid-metal coolant handling and chemistry, and fast-spectrum reactor physics. A new licensing basis: a different design, a different safety case and different regulatory questions.","text_ar":"مناولة المبرد المعدني السائل وكيمياؤه، وفيزياء المفاعلات ذات الطيف السريع. أساس ترخيص جديد: تصميم مختلف وحالة سلامة مختلفة وأسئلة تنظيمية مختلفة."}]'::jsonb, 'Fast reactors with liquid-metal coolant: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; factory fabrication adapts. Planning assumption; no deployment decision implied.', 'المفاعلات السريعة المبرّدة بالمعادن السائلة: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التصنيع في المصنع. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Tracking regulatory commitments and keeping a precise, honest licensing basis stay the same.', 'تبقى متابعة الالتزامات التنظيمية ودقة أساس الترخيص ونزاهته كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-fs-adv-fuelcycle","level":2},{"skill_id":"sk-fs-adv-regulation","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, array['fr-adv-licensing']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 57, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:regulatory-affairs-licensing-engineer:tech-intl', 'regulatory-affairs-licensing-engineer', 'tech-intl', 4, false, '[{"dim":"systems","change":"adapts","text_en":"Other large reactor designs, such as the AP1000, bring their own systems and documentation. A new licensing basis: a different design, a different safety case and different regulatory questions.","text_ar":"تأتي تصاميم مفاعلات كبيرة أخرى، مثل AP1000، بأنظمتها ووثائقها الخاصة. أساس ترخيص جديد: تصميم مختلف وحالة سلامة مختلفة وأسئلة تنظيمية مختلفة."},{"dim":"delivery","change":"new","text_en":"Project delivery abroad, investment and owner''s-engineer work for partners. Working with regulators and partners in other countries.","text_ar":"تنفيذ المشاريع في الخارج والاستثمار وأعمال مهندس المالك للشركاء. العمل مع الجهات التنظيمية والشركاء في دول أخرى."}]'::jsonb, 'International projects: the biggest shifts for this role are project delivery; plant systems, coolant and fuel adapts. Planning assumption; no deployment decision implied.', 'المشاريع الدولية: أكبر التحولات لهذا الدور في تنفيذ المشاريع، بينما يتكيف كل من أنظمة المحطة والمبرد والوقود. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Tracking regulatory commitments and keeping a precise, honest licensing basis stay the same.', 'تبقى متابعة الالتزامات التنظيمية ودقة أساس الترخيص ونزاهته كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-en-01-project","level":2},{"skill_id":"sk-fs-adv-regulation","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"nucleareurope-match","label":"nucleareurope · MATCH programme: a tool for nuclear capacity building in France","url":"https://www.nucleareurope.eu/blog/highlight-of-the-month/match-program-a-tool-for-nuclear-capacity-building-in-france/","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 58, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:human-performance-specialist:tech-micro', 'human-performance-specialist', 'tech-micro', 1, false, '[{"dim":"multi_module","change":"adapts","text_en":"Many small transportable units rather than one plant. Performance trends and lessons learned compare several units.","text_ar":"وحدات صغيرة كثيرة قابلة للنقل بدلاً من محطة واحدة. تقارن اتجاهات الأداء والدروس المستفادة بين عدة وحدات."},{"dim":"passive_safety","change":"new","text_en":"Microreactor concepts are designed to cool themselves passively for long periods. Human performance shifts from manual action to monitoring passive systems and avoiding complacency.","text_ar":"صُممت مفاهيم المفاعلات المتناهية الصغر لتبريد نفسها بطريقة خاملة لفترات طويلة. ينتقل الأداء البشري من الإجراء اليدوي إلى مراقبة الأنظمة الخاملة وتجنب التراخي."},{"dim":"digital_ic","change":"adapts","text_en":"Remote and autonomous operation concepts: monitoring from a distance rather than from a local control room. Human-system interface reviews of new screens and alarms.","text_ar":"مفاهيم التشغيل عن بعد والتشغيل الذاتي: المراقبة من بعيد بدلاً من غرفة تحكم محلية. مراجعات واجهة الإنسان والنظام للشاشات والإنذارات الجديدة."}]'::jsonb, 'Microreactors: the biggest shifts for this role are passive safety; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'المفاعلات المتناهية الصغر: أكبر التحولات لهذا الدور في السلامة الخاملة، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Safety culture traits, independent oversight and the corrective action programme stay the same.', 'تبقى سمات ثقافة السلامة والرقابة المستقلة وبرنامج الإجراءات التصحيحية كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-regulation","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-adv-micro-l1"},{"kind":"course","ref":"c-fs-remote"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 59, 'p-training-mgr', '2026-10-11T08:00:00Z')
